package com.production.maintenance.model;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="breakdowns") public class Breakdown { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long machineId; private String description; private String severity="MEDIUM"; private String status="OPEN"; private LocalDateTime reportedAt=LocalDateTime.now(); private LocalDateTime resolvedAt; private Double downtimeHours; public Breakdown(){} public Long getId(){return id;} public void setId(Long v){id=v;} public Long getMachineId(){return machineId;} public void setMachineId(Long v){machineId=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getSeverity(){return severity;} public void setSeverity(String v){severity=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public LocalDateTime getReportedAt(){return reportedAt;} public void setReportedAt(LocalDateTime v){reportedAt=v;} public LocalDateTime getResolvedAt(){return resolvedAt;} public void setResolvedAt(LocalDateTime v){resolvedAt=v;} public Double getDowntimeHours(){return downtimeHours;} public void setDowntimeHours(Double v){downtimeHours=v;} }
